explanation:
To find how much time passed, subtract the start time from the click time.
```javascript
let startedAt = null;
let elapsed = null;
function signal(now) {
  startedAt = now;
  elapsed = null;
}
function clickAt(now) {
  if (startedAt !== null) {
    elapsed = Math.max(0, now - startedAt);
  }
}
signal(2000);
clickAt(2180);
console.log(elapsed);
```
Output:
```text
180
```
`signal(2000)` saves the start. `clickAt(2180)` finds the difference: 2180 − 2000 = 180 milliseconds. These functions update the saved variables.

Resetting clears both saved values so another round can begin.
```javascript
let startedAt = null;
let elapsed = null;
function signal(now) {
  startedAt = now;
  elapsed = null;
}
function clickAt(now) {
  if (startedAt !== null) {
    elapsed = Math.max(0, now - startedAt);
  }
}
function reset() {
  startedAt = null;
  elapsed = null;
}
clickAt(1500);
console.log(elapsed);
signal(2000);
clickAt(2200);
reset();
console.log(startedAt, elapsed);
```
Output:
```text
null
null null
```
The early click is ignored. Later, `reset()` clears both the start time and the result.

