    try encodeEntries(entries).write(to: url, options: .atomic)
}
func loadEntries(from url: URL) -> LoadResult {
    do { return loadEntries(try Data(contentsOf: url)) }
    catch { return LoadResult(entries: [], message: "Saved file could not be read; starting with an empty list.") }
