solution:
function App() {
 const [selected,setSelected] = React.useState("all");
 const [filter,setFilter] = React.useState("all");
 const [isPending,startTransition] = React.useTransition();
 const items = ["apple","apricot","berry"];
 function choose(next) {
  setSelected(next);
  startTransition(() => setFilter(next));
 }
 const shown = items.filter(item=>filter === "all" || item.startsWith(filter));
 return <main><button onClick={()=>choose("a")}>Show a</button><button onClick={()=>choose("b")}>Show b</button><button onClick={()=>choose("all")}>Show all</button>
 <p data-selected={selected}>Selected: {selected}</p><p role="status">{isPending ? "Updating" : "Ready"}</p><ul>{shown.map(item=><li key={item}>{item}</li>)}</ul></main>;
}

