  let total = 0;
  for (let i = 0; i <= values.length; i += 1) {
    total += values[i];
  }
  return total;
}

solution:
function totalValues(values) {
  let total = 0;
  for (let i = 0; i < values.length; i += 1) {
    total += values[i];
  }
  return total;
}

